 PERFORM private.org_require('org.manage_structure',old_.unit_id);
 IF NOT EXISTS(SELECT 1 FROM org_position_slots s WHERE s.id=v->>'slot_id' AND s.unit_id=old_.unit_id AND s.title_id=old_.title_id AND s.role_id=v->>'reviewed_role') THEN RAISE EXCEPTION 'Mapping phải xem trước đúng Role, chức danh và đơn vị.'; END IF;
 UPDATE org_assignments SET slot_id=v->>'slot_id',data=jsonb_set(data,'{slot_id}',to_jsonb(v->>'slot_id')),revision=revision+1 WHERE id=id_;
 affected:=affected||jsonb_build_array(old_.unit_id);
 ELSIF x->>'action'='unit' THEN SELECT * INTO old_ FROM org_units WHERE id=id_;parent_:=nullif(v->>'parent_id',''); IF parent_ IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',parent_);END IF; IF old_.id IS NOT NULL THEN PERFORM private.org_require('org.manage_structure',old_.id);IF old_.kind<>v->>'kind' THEN RAISE EXCEPTION 'Không đổi loại đơn vị đã tồn tại.';END IF; ELSIF parent_ IS NULL AND NOT private.is_super_admin(auth.uid()) THEN RAISE EXCEPTION 'Chỉ Super Admin tạo đơn vị gốc.';END IF;
 IF coalesce(trim(v->>'name'),'')='' OR v->>'kind' NOT IN ('company','block','system','department','team') THEN RAISE EXCEPTION 'Đơn vị không hợp lệ.';END IF; IF parent_=id_ OR private.org_contains(id_,parent_) THEN RAISE EXCEPTION 'Cơ cấu bị vòng lặp.';END IF;
 IF parent_ IS NOT NULL AND NOT EXISTS(SELECT 1 FROM org_units WHERE id=parent_ AND active) THEN RAISE EXCEPTION 'Đơn vị cha đã ngừng hoặc không tồn tại.';END IF;
 IF NOT coalesce((v->>'active')::boolean,true) AND (EXISTS(SELECT 1 FROM org_units WHERE parent_id=id_ AND active) OR EXISTS(SELECT 1 FROM org_assignments WHERE unit_id=id_ AND status<>'cancelled' AND (ends_at IS NULL OR ends_at>clock_timestamp()))) THEN RAISE EXCEPTION 'Đơn vị còn đơn vị con hoặc phân công hiệu lực/tương lai.';END IF;
